use super::{CACHE_CLEANUP_FALLBACK_RUNNER, CACHE_CLEANUP_PATH, render_cache_cleanup_yml};

const MARKER: &str =
    "# Generated by Velnor Actions 0.1.22; edit .velnor/config.toml and regenerate.\n";

fn render(label: &str) -> String {
    render_cache_cleanup_yml(label, "0.1.22")
        .expect("render")
        .bytes
}

#[test]
fn the_workflow_is_marked_and_runs_only_when_a_pull_request_closes() {
    let file = render_cache_cleanup_yml("ubuntu-26.04", "0.1.22").expect("render");
    assert_eq!(file.path, CACHE_CLEANUP_PATH);
    assert!(file.bytes.starts_with(MARKER));
    let yaml = &file.bytes;
    assert!(yaml.contains("\"on\":\n  pull_request:\n    types:\n      - closed\n"));
    assert!(yaml.contains("runs-on: ubuntu-26.04\n"));
}

#[test]
fn forks_never_run_and_actions_write_is_the_one_job_permission() {
    let yaml = render("ubuntu-26.04");
    assert!(yaml.contains("if: github.event.pull_request.head.repo.fork == false"));
    assert!(
        yaml.contains("permissions: {}\n"),
        "workflow scope is empty"
    );
    assert_eq!(yaml.matches("actions: write").count(), 1);
    assert!(!yaml.contains("contents:"), "no repository scope");
    assert!(!yaml.contains("actions/checkout"), "no code is checked out");
}

#[test]
fn only_the_closed_pull_requests_own_ref_is_listed_and_nothing_is_interpolated() {
    let yaml = render("ubuntu-26.04");
    assert!(yaml.contains("PR_REF: refs/pull/${{ github.event.pull_request.number }}/merge"));
    assert!(yaml.contains("gh cache list --ref \\\"$PR_REF\\\""));
    assert!(!yaml.contains("--all"), "no global delete");
    let run = yaml.split("        run: ").nth(1).expect("run line");
    assert!(!run.contains("${{"), "the script takes everything from env");
    assert!(
        run.starts_with('"') && !run.contains("|\n"),
        "a lintable single-line script"
    );
}

#[test]
fn a_scale_set_runner_falls_back_to_a_hosted_label_with_the_cli() {
    assert!(render("ubuntu-26.04").contains("runs-on: ubuntu-26.04\n"));
    let scale = render_cache_cleanup_yml("velnor", "0.1.22");
    // A bare custom label is a scale-set selector only when it parses as one.
    if let Ok(file) = scale {
        assert!(
            file.bytes.contains("runs-on: velnor\n")
                || file
                    .bytes
                    .contains(&format!("runs-on: {CACHE_CLEANUP_FALLBACK_RUNNER}\n"))
        );
    }
}
